const http=require('node:http');const {createHash}=require('node:crypto');
const sha=x=>createHash('sha256').update(x).digest('hex');
const asset=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+pbbkAAAAASUVORK5CYII=','base64');
function pkg(n){const body=`Synthetic primary body ${n}\nA second paragraph.`;return {protocol:'owned_provider_v1',provider:'dzen',projectId:n,taskId:n+100,channelId:n+200,revision:2,decisionId:n+300,decisionVersion:1,selectedAssetId:n+400,bodySha256:sha(body),assetSha256:sha(asset),schedule:'2026-10-18T10:00:00.000Z',manifest:'synthetic-current',accountId:`fixture_account_${n}`,body,title:`Synthetic accepted title ${n}`,assetUrl:'https://fixture-assets.supabase.co/cover.png',approvalReference:'synthetic accepted approval',releaseActorId:'user:1',digest:sha('synthetic-package-'+n),releaseId:n+500};}
function claim(p){return {attemptId:p.taskId+1000,key:`synthetic-${p.taskId}`,package:p,generation:1,jobId:`synthetic-job-${p.taskId}`,workItemId:p.taskId+2000,leaseSha256:sha('synthetic-lease')};}
async function server(){
 const objects=new Map();let next=0,submits=0,uploads=0,unexpected=0,wrongProof=false,corruptPublishedCover=false,corruptPublishedBody=false,duplicateSubmit=false,duplicateCreate=false,createResponseMode="normal",submitResponseMode="normal",delayedAutosave=false,pendingAutosave,releaseArmed=false;const requests=[];
 function html(account,objectId){return `<!doctype html><meta charset="utf-8"><style>#title,#body{white-space:pre-wrap;min-height:40px;min-width:200px;border:1px solid black}</style><button data-testid="add-publication-button" onclick="document.querySelector('[aria-label]').hidden=false">Create</button><button role="button" aria-label="Написать статью" hidden onclick="createArticle()">Article</button>${objectId?`<div contenteditable="true" role="textbox" id="title"><h1 data-block="true">${objects.get(objectId)?.title||''}</h1></div><div contenteditable="true" role="textbox" id="body"><div class="zen-editor-block">${wrongProof?'wrong primary body':objects.get(objectId)?.body||''}</div></div><input type="file" accept="image/png"><button data-testid="article-publish-btn" onclick="document.querySelector('[role=dialog]').hidden=false">Next</button><div role="dialog" hidden><button data-testid="publish-btn" onclick="submitArticle()">Опубликовать</button></div>`:''}<script>
 const account=${JSON.stringify(account)},objectId=${JSON.stringify(objectId||'')};
 async function createArticle(){const first=fetch('/editor-api/v2/publisher/'+account+'/publication',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'native-ui-create'})});if(${duplicateCreate})void fetch('/editor-api/v2/publisher/'+account+'/publication',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'native-ui-create'})}).catch(()=>{});const r=await first;const p=await r.json();location.href='/profile/editor/id/'+account+'/'+p.id+'/edit';}
 async function save(){if(!objectId)return;for(const [id,tag,attr]of [['title','h1','data-block'],['body','div','class']]){const el=document.getElementById(id);if(!el.querySelector(tag)){const text=el.innerText;el.innerText='';const child=document.createElement(tag);child.setAttribute(attr,id==='title'?'true':'zen-editor-block');child.innerText=text;el.append(child);}}await fetch('/editor-api/v2/publisher/'+account+'/publication/'+objectId,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({title:document.querySelector('#title').innerText,body:document.querySelector('#body').innerText})});if(${delayedAutosave}&&document.querySelector('#body').innerText)void fetch('/editor-api/v2/publisher/'+account+'/publication/'+objectId,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({title:document.querySelector('#title').innerText,body:'delayed autosave changed native body'})});}
 document.querySelector('#title')?.addEventListener('input',save);document.querySelector('#body')?.addEventListener('input',save);
 document.querySelector('input')?.addEventListener('change',async e=>{await fetch('/editor-api/v2/add-image?object='+objectId,{method:'POST',body:e.target.files[0]});});
 async function submitArticle(){const request=fetch('/editor-api/v2/publisher/'+account+'/publication/'+objectId+'/publish',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objectId})});if(${duplicateSubmit}){await Promise.all([request,fetch('/editor-api/v2/publisher/'+account+'/publication/'+objectId+'/publish',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objectId})})]);}else await request;}
 </script>`;}
 const native=http.createServer(async(req,res)=>{try{
  const u=new URL(req.url,'http://127.0.0.1'),host=u.searchParams.get('__native_host')||'dzen.ru';u.searchParams.delete('__native_host');const observation={method:req.method,path:u.pathname,host};requests.push(observation);if(req.method==='POST'&&(u.pathname.endsWith('/publication')||u.pathname.endsWith('/publish'))){let body='';for await(const part of req){body+=part;if(body.length>65536)throw Error('fixture request limit');}observation.body=body;observation.contentType=req.headers['content-type'];}
  const json=value=>{const b=Buffer.from(JSON.stringify(value));res.writeHead(200,{'content-type':'application/json','content-length':b.length,'access-control-allow-origin':'*'});res.end(b);};
  const bytes=value=>{res.writeHead(200,{'content-type':'image/png','content-length':value.length,'access-control-allow-origin':'*'});res.end(value);};
  if(host==='fixture-assets.supabase.co')return bytes(asset);
  if(host==='avatars.dzeninfra.ru'){const id=u.pathname.match(/pub_([^/]+)_cover\/orig$/)?.[1];return bytes(corruptPublishedCover&&objects.get(id)?.isPublished?Buffer.from('unverified transformed bytes'):objects.get(id)?.cover||Buffer.from('missing'));}
  if(u.pathname==='/favicon.ico'){res.writeHead(204);res.end();return;}
  const account=u.pathname.match(/\/(?:editor\/id|publishers|publisher)\/([^/]+)/)?.[1];
  if(u.pathname.includes('/profile/editor/id/')){const objectId=u.pathname.match(/\/([^/]+)\/edit$/)?.[1];res.writeHead(200,{'content-type':'text/html'});res.end(html(account,objectId));if(objectId&&releaseArmed&&pendingAutosave)pendingAutosave();return;}
  if(u.pathname.startsWith('/editor-api/v3/publishers/'))return json({publisher:{id:account},accessData:{canRead:true,canWrite:true}});
  if(u.pathname==='/editor-api/v3/publications'){const requested=u.searchParams.get('publisherId'),state=u.searchParams.get('state');return json({publications:[...objects.values()].filter(x=>x.publisherId===requested&&x.status===state).map(x=>({...x,bodySha256:sha(x.body)})),hasMore:false});}
  if(u.pathname==='/editor-api/v2/add-image'&&req.method==='POST'){const chunks=[];for await(const c of req)chunks.push(c);objects.get(u.searchParams.get('object')).cover=Buffer.concat(chunks);uploads++;return json({uploaded:true});}
  if(u.pathname.endsWith('/publication')&&req.method==='POST'){if(createResponseMode==='redirect'){res.writeHead(307,{location:u.pathname});res.end();return;}if(createResponseMode==='oversize'){res.writeHead(200,{'content-type':'application/json'});res.write('{"pad":"');for(let i=0;i<33;i++)res.write('x'.repeat(65536));res.end('"}');return;}const id=`native_object_${++next}`;objects.set(id,{id,publisherId:account,title:'',body:'',status:'draft',isPublished:false,imageId:'cover'});return json({id,publisherId:account});}
  const id=u.pathname.match(/\/publication\/([^/]+)/)?.[1],row=objects.get(id);
  if(row&&row.publisherId===account){
   if(u.pathname.endsWith('/publish')&&req.method==='POST'){if(corruptPublishedBody)row.body='unexpected native persisted body';row.status='published';row.isPublished=true;row.publishTime=Date.now();row.commonUrl='https://dzen.ru/a/'+id;submits++;if(submitResponseMode==='redirect'){res.writeHead(307,{location:u.pathname});res.end();return;}if(submitResponseMode==='oversize'){res.writeHead(200,{'content-type':'application/json'});res.write('{"pad":"');for(let i=0;i<33;i++)res.write('x'.repeat(65536));res.end('"}');return;}return json({publication:{id,publisherId:account}});}
   if(req.method==='PUT'){let body='';for await(const c of req){body+=c;if(body.length>65536)throw Error('fixture limit');}const payload=JSON.parse(body);if(delayedAutosave&&payload.body==='delayed autosave changed native body'){const previous=pendingAutosave;pendingAutosave=()=>{previous?.();Object.assign(row,payload);json({saved:true});pendingAutosave=undefined;};return;}Object.assign(row,payload);return json({saved:true});}
   if(req.method==='GET')return json({publications:[{...row,content:{preview:{image:{id:'cover',sizes:{orig:{url:`https://avatars.dzeninfra.ru/get-zen_doc/123/pub_${id}_cover/orig`}}}}}}]});
  }
  unexpected++;res.writeHead(404);res.end();
 }catch{unexpected++;res.writeHead(500);res.end();}});
 await new Promise(resolve=>native.listen(0,'127.0.0.1',resolve));
 return {port:native.address().port,objects,requests,get submits(){return submits;},get uploads(){return uploads;},get unexpected(){return unexpected;},set wrongProof(value){wrongProof=value;},set corruptPublishedCover(value){corruptPublishedCover=value;},set corruptPublishedBody(value){corruptPublishedBody=value;},set duplicateSubmit(value){duplicateSubmit=value;},set duplicateCreate(value){duplicateCreate=value;},set createResponseMode(value){createResponseMode=value;},set submitResponseMode(value){submitResponseMode=value;},set delayedAutosave(value){delayedAutosave=value;},get pendingAutosave(){return Boolean(pendingAutosave);},releaseDelayed(){releaseArmed=true;setTimeout(()=>pendingAutosave?.(),200);},close:async()=>{native.closeAllConnections();await new Promise(resolve=>native.close(resolve));}};
}
module.exports={server,pkg,claim,asset,sha};
